"""Job options shared by execution, preview, and heartbeat scheduling."""

def execution_options(options):
    """Missing/None retries mean 3; zero means no retries."""
    retries = options.get("retries")
    if retries is None:
        retries = 3
    return {"retries": retries, "queue": options.get("queue", "default")}


def preview_options(options):
    """Preview uses the same retries contract as execution."""
    retries = options.get("retries")
    if retries is None:
        retries = 3
    return {"attempts": retries + 1}


def heartbeat_seconds(options):
    """Missing, None, or zero heartbeat select the 30-second service default."""
    return options.get("heartbeat") or 30
import unittest
from job_options import execution_options, preview_options, heartbeat_seconds

class PublicTests(unittest.TestCase):
    def test_explicit_no_retry(self):
        self.assertEqual(execution_options({"retries": 0})["retries"], 0)

    def test_preview_explicit_no_retry(self):
        self.assertEqual(preview_options({"retries": 0}), {"attempts": 1})

    def test_defaults(self):
        self.assertEqual(execution_options({})["retries"], 3)
        self.assertEqual(execution_options({"retries": None})["retries"], 3)
        self.assertEqual(preview_options({}), {"attempts": 4})
        self.assertEqual(preview_options({"retries": None}), {"attempts": 4})
        self.assertEqual(heartbeat_seconds({}), 30)
        self.assertEqual(heartbeat_seconds({"heartbeat": 0}), 30)
